static void reset_case(void)
{
    rx_full = rx_len = now_ms = ident_replies = requests = 0;
    dispatches = ownership_errors = ota_polls = platform_errors = 0;
    dispatched_n = 0; late_frame = NULL; late_n = 0;
    fm1_ms = ed_reboot_at = 0;
